					OR Target.[IsIdentityColumnFlag] <> Source.[IsIdentityColumnFlag]) THEN
	UPDATE SET 
				  [SyncTableToScopeMapGuid] = Source.[SyncTableToScopeMapGuid]
				, [ColumnName] = Source.[ColumnName]
				, [ColumnIndex] = Source.[ColumnIndex]
				, [ColumnType] = Source.[ColumnType]
				, [ColumnSize] = Source.[ColumnSize]
				, [ColumnPrecision] = Source.[ColumnPrecision]
				, [ColumnScale] = Source.[ColumnScale]
				, [IsNullableFlag] = Source.[IsNullableFlag]
				, [IsPrimaryKeyMemberFlag] = Source.[IsPrimaryKeyMemberFlag]
				, [IsIdentityColumnFlag] = Source.[IsIdentityColumnFlag]
				, [CreatedDate] = Source.[CreatedDate]
				, [CreatedBy] =	Source.[CreatedBy]
				, [UpdatedDate] = Source.[UpdatedDate]
				, [UpdatedBy] =	Source.[UpdatedBy]
WHEN NOT MATCHED THEN
	INSERT ([SyncTableToScopeMapColumnGuid], [SyncTableToScopeMapGuid], [ColumnName], [ColumnIndex], 
	[ColumnType], [ColumnSize], [ColumnPrecision], [ColumnScale], [IsNullableFlag], [IsPrimaryKeyMemberFlag], 
	[IsIdentityColumnFlag], [CreatedDate], [CreatedBy], [UpdatedDate], [UpdatedBy])
		VALUES (Source.[SyncTableToScopeMapColumnGuid], Source.[SyncTableToScopeMapGuid], Source.[ColumnName], Source.[ColumnIndex],
		Source.[ColumnType], Source.[ColumnSize], Source.[ColumnPrecision], Source.[ColumnScale], Source.[IsNullableFlag], Source.[IsPrimaryKeyMemberFlag],
		Source.[IsIdentityColumnFlag], Source.[CreatedDate],Source.[CreatedBy],Source.[UpdatedDate],Source.[UpdatedBy])
OUTPUT
	$action AS ActionType,
	deleted.[SyncTableToScopeMapColumnGuid], 
	inserted.[SyncTableToScopeMapColumnGuid], 
	deleted.[SyncTableToScopeMapGuid], 
	inserted.[SyncTableToScopeMapGuid], 
	deleted.[ColumnName], 
	inserted.[ColumnName], 
	deleted.[ColumnIndex],
	inserted.[ColumnIndex],
	deleted.[ColumnType], 
	inserted.[ColumnType], 
	deleted.[ColumnSize], 
	inserted.[ColumnSize], 
	deleted.[ColumnPrecision], 
	inserted.[ColumnPrecision], 
	deleted.[ColumnScale], 
	inserted.[ColumnScale], 
	deleted.[IsNullableFlag], 
	inserted.[IsNullableFlag], 
	deleted.[IsPrimaryKeyMemberFlag],
	inserted.[IsPrimaryKeyMemberFlag],
	deleted.[IsIdentityColumnFlag], 
	inserted.[IsIdentityColumnFlag], 
	deleted.[CreatedDate],
	inserted.[CreatedDate],
	deleted.[CreatedBy],
	inserted.[CreatedBy],
	deleted.[UpdatedDate],
	inserted.[UpdatedDate],
	deleted.[UpdatedBy],
	inserted.[UpdatedBy],
	deleted.[_ClusterIdx],
	inserted.[_ClusterIdx]
INTO @tblSyncTableToScopeMapColumnData;

SELECT @SyncTableToScopeMapColumnDataInserted = COUNT(*) FROM @tblSyncTableToScopeMapColumnData WHERE ActionType IN ( 'INSERT' );
SELECT @SyncTableToScopeMapColumnDataUpdated = COUNT(*) FROM @tblSyncTableToScopeMapColumnData WHERE ActionType IN ( 'UPDATE' )
SELECT @SyncTableToScopeMapColumnDataDeleted = COUNT(*) FROM @tblSyncTableToScopeMapColumnData WHERE ActionType IN ( 'DELETE' )

IF (@SyncTableToScopeMapColumnDataInserted > 0)
BEGIN
	PRINT '** ' + CONVERT(NVARCHAR(25), @SyncTableToScopeMapColumnDataInserted) + ' NEW RECORDS INSERTED INTO [sync].[tblSyncTableToScopeMapColumn] **'
	PRINT ''
END

IF (@SyncTableToScopeMapColumnDataUpdated > 0)
BEGIN
	PRINT '** ' + CONVERT(NVARCHAR(25), @SyncTableToScopeMapColumnDataUpdated) + ' EXISTING RECORDS UPDATED IN [sync].[tblSyncTableToScopeMapColumn] **'
	PRINT ''
	SELECT * FROM @tblSyncTableToScopeMapColumnData WHERE ActionType IN ( 'UPDATE' );
END

SET NOCOUNT OFF

